(function (DM) {
    DM.load = async (onload) => {
        const res = await fetch("https://www.jma.go.jp/bosai/quake/data/list.json");
        if (res.status != 200)
            return;
        const data = await res.json();
        // const data = jma as src_record [] ;
        const list = new Map;
        data.forEach((src, n) => {
            const diff = list.get(src.eid);
            if (!diff ||
                diff && (src.ser > diff.ser)) {
                src.ctt = ctt(src.ctt);
                src.eid = ctt(src.eid);
                list.set(src.eid, src);
            }
        });
        onload([...list.values()]);
    };
    function ctt(s) {
        return s.replace(/(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})/, (z, y, m, d, h, mi, s) => `${y}-${m}-${d}-${h}:${mi}:${s}`);
    }
})(DM || (DM = {}));
